<template>
  <main class="ledger-page ad-calendar" :aria-busy="loading">
    <header class="ledger-heading"><div><span class="ledger-eyebrow">广告经营 · 排期</span><h1>广告位排期</h1><p>先看余量，再安排下一笔合作。</p></div><a-button @click="router.push('/ads')">投放管理</a-button></header>
    <section class="ledger-panel">
      <div class="calendar-toolbar"><div><a-button aria-label="上个月" @click="move(-1)">←</a-button><strong>{{ month.replace('-', ' 年 ') }} 月</strong><a-button aria-label="下个月" @click="move(1)">→</a-button><a-button @click="goToday">本月</a-button></div><a-button :loading="loading" @click="load">刷新</a-button></div>
      <p class="calendar-caption">{{ data?.note || '按北京时间统计，开始日包含，到期日不包含。' }}</p>
      <div v-if="error" class="ledger-error" role="alert">{{ error }}<a-button @click="load">重新加载</a-button></div>
      <div v-if="data" class="calendar-scroll"><div class="calendar-grid"><div v-for="name in ['一','二','三','四','五','六','日']" :key="name" class="calendar-week">周{{ name }}</div><div v-for="n in data.week_start" :key="'blank'+n" class="calendar-blank"/><button v-for="day in data.days" :key="day.day" class="calendar-day" :class="{selected: selected===day.day,today:day.day===data.today}" :aria-label="day.day" :aria-pressed="selected===day.day" @click="selected=day.day"><div class="calendar-date"><b>{{ Number(day.day.slice(-2)) }}</b><small v-if="day.day===data.today">今天</small><small v-else-if="day.ending_ad_ids.length">{{ day.ending_ad_ids.length }} 条到期</small></div><div class="calendar-mini" aria-hidden="true"><i v-for="p in day.placements" :key="p.slot" :class="{full:p.capacity!=null && p.remaining===0,occupied:p.used>0}" /></div><div v-for="p in day.placements" :key="p.slot" class="calendar-position" :class="{full:p.capacity!=null && p.remaining===0,over:p.capacity!=null && p.used>p.capacity}"><span>{{ shortNames[p.slot] }}</span><b>{{ p.capacity==null ? p.used+' 条' : p.used+'/'+p.capacity }}</b></div><small class="calendar-pending" v-if="day.pending_order_ids.length">{{ day.pending_order_ids.length }} 笔待安排</small></button></div></div>
      <div class="calendar-legend"><span><i/> 有余量</span><span><i class="full"/> 已满</span><span>页脚不限名额，显示当日在投条数</span><span class="calendar-mobile-tip">圆点依次为角标、顶部、页脚；点日期查看明细</span></div>
    </section>
    <section v-if="current" class="ledger-panel calendar-detail"><div class="ledger-section-heading"><div><h2>{{ selected }} · 位置明细</h2><p>已安排以实际投放为准，待安排订单需检查后同步广告。</p></div><a-button @click="router.push('/ad-orders/new')">登记订单</a-button></div><div class="calendar-placement-grid"><article v-for="p in current.placements" :key="p.slot"><header><b>{{ p.label }}</b><span :class="{'ledger-amber':p.remaining===0}">{{ p.capacity==null ? '不限名额' : p.used>p.capacity ? '超出容量，请调整' : p.remaining===0 ? '已满' : '余 '+p.remaining+' 位' }}</span></header><p class="ledger-small">{{ p.used }} 条已安排{{ p.capacity==null ? '' : ' / 最多 '+p.capacity+' 条' }}</p><button v-for="id in p.ad_ids" :key="id" class="calendar-ad" @click="router.push('/ads/'+id)"><b>{{ adById[id]?.name }}</b><small>{{ adById[id]?.start_date }} → {{ adById[id]?.end_date }} 撤下 ↗</small></button><p v-if="!p.ad_ids.length" class="calendar-empty">当天尚无投放</p></article></div><div class="calendar-followup"><article><h3>待安排订单 · {{ current.pending_order_ids.length }}</h3><p class="ledger-small">尚未由关联广告覆盖，不占投放名额；报价时也请核对这些合作。</p><button v-for="id in current.pending_order_ids" :key="id" class="calendar-ad" @click="router.push('/ad-orders/'+id)"><b>{{ orderById[id]?.title }}</b><small>{{ SLOT[orderById[id]?.slot] }} · {{ orderById[id]?.start_date }} → {{ orderById[id]?.end_date }} ↗</small></button><p v-if="!current.pending_order_ids.length" class="calendar-empty">当天没有待安排订单</p></article><article><h3>当天到期撤下 · {{ current.ending_ad_ids.length }}</h3><button v-for="id in current.ending_ad_ids" :key="id" class="calendar-ad" @click="router.push('/ads/'+id)"><b>{{ adById[id]?.name }}</b><small>当天 00:00 撤下，不计入当天占用 ↗</small></button><p v-if="!current.ending_ad_ids.length" class="calendar-empty">当天没有广告到期</p></article></div></section>
  </main>
</template>
<script setup>
import { computed,onMounted,ref } from 'vue';
import { useRouter } from 'vue-router';
import { api,SLOT,todayText } from '../api';
import '../ad-orders.css';
const router=useRouter(),month=ref(todayText().slice(0,7)),selected=ref(todayText()),data=ref(null),loading=ref(false),error=ref('');
const shortNames={sponsor:'左右角标',list_top:'列表顶部',footer:'全站页脚'};
let request=0;
const current=computed(()=>data.value?.days.find(day=>day.day===selected.value));
const adById=computed(()=>Object.fromEntries((data.value?.ads || []).map(row=>[row.id,row])));
const orderById=computed(()=>Object.fromEntries((data.value?.pending_orders || []).map(row=>[row.id,row])));
async function load(){const serial=++request;loading.value=true;error.value='';try{const result=await api('/api/ads/calendar?month='+month.value);if(serial===request){data.value=result;if(!result.days.some(day=>day.day===selected.value))selected.value=result.days[0].day;}}catch(err){if(serial===request){error.value=err.message;data.value=null;}}finally{if(serial===request)loading.value=false;}}
function move(delta){const d=new Date(month.value+'-01T00:00:00Z');d.setUTCMonth(d.getUTCMonth()+delta);month.value=d.toISOString().slice(0,7);load();}
function goToday(){month.value=todayText().slice(0,7);selected.value=todayText();load();}
onMounted(load);
</script>
<style>
.calendar-toolbar,.calendar-toolbar>div{display:flex;align-items:center;gap:12px}.calendar-toolbar{justify-content:space-between;padding:22px 24px 8px}.calendar-toolbar strong{font-size:18px;color:#223b52}.calendar-caption{margin:8px 24px 20px;color:#7c8d9c;font-size:12px;line-height:1.8}.calendar-scroll{overflow-x:auto;margin:0 24px}.calendar-grid{display:grid;grid-template-columns:repeat(7,minmax(106px,1fr));min-width:760px;gap:1px;background:#e5ebed;border:1px solid #e5ebed;border-radius:10px;overflow:hidden}.calendar-week{text-align:center;background:#f6f8f8;padding:12px;color:#7c8c94;font-size:12px}.calendar-blank{background:#fafbfb}.calendar-day{border:0;border-radius:0;text-align:left;background:white;padding:12px 11px;min-height:145px;cursor:pointer;color:#4b626d;position:relative;outline-offset:-3px}.calendar-day:hover{background:#f8fbfa}.calendar-day.selected{box-shadow:inset 0 0 0 2px #64835a;background:#f5f9f2}.calendar-date{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.calendar-date b{font-size:17px;color:#273f50}.calendar-date small{font-size:10px;color:#85949c}.today .calendar-date b{color:#668648}.calendar-position{display:flex;justify-content:space-between;gap:8px;font-size:10px;margin:5px 0}.calendar-position b{font-variant-numeric:tabular-nums;color:#66844f;font-weight:500}.calendar-position.full b{color:#b38b43}.calendar-position.over b{color:#c65843}.calendar-pending{display:block;color:#b18745;font-size:10px;margin-top:10px}.calendar-legend{padding:18px 24px;display:flex;gap:24px;flex-wrap:wrap;color:#84949e;font-size:11px}.calendar-legend i{display:inline-block;width:6px;height:6px;border-radius:50%;background:#7d9c64;margin-right:5px}.calendar-legend i.full{background:#bd985b}.calendar-placement-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;padding:0 24px 24px}.calendar-placement-grid>article{padding:18px;border:1px solid #e6ebec;border-radius:9px;min-width:0}.calendar-placement-grid header{display:flex;justify-content:space-between;gap:8px;color:#324b59;font-size:12px}.calendar-placement-grid header>span{color:#73935b;font-size:11px}.calendar-ad{display:block;width:100%;text-align:left;cursor:pointer;background:#f7f9f9;border:0;border-radius:7px;padding:12px;margin-top:9px;color:#425b66;overflow-wrap:anywhere}.calendar-ad b,.calendar-ad small{display:block}.calendar-ad b{font-size:12px;font-weight:500}.calendar-ad small{color:#8b9aa2;font-size:10px;margin-top:6px;line-height:1.6}.calendar-empty{font-size:11px;color:#9aa7ad;margin:20px 0 6px}.calendar-followup{border-top:1px solid #edf0f1;padding:22px 24px;display:grid;grid-template-columns:1fr 1fr;gap:24px}.calendar-followup h3{font-size:13px;font-weight:500;color:#405b68;margin:0 0 10px}@media(max-width:800px){.calendar-toolbar{padding:18px 16px 6px;gap:8px}.calendar-toolbar>div{gap:6px}.calendar-toolbar strong{font-size:14px}.calendar-caption{margin:10px 16px 16px}.calendar-scroll{margin:0 16px}.calendar-placement-grid{grid-template-columns:1fr;padding:0 16px 16px}.calendar-followup{grid-template-columns:1fr;padding:18px 16px}.calendar-legend{padding:16px;gap:12px}}

.calendar-mini,.calendar-mobile-tip{display:none}.calendar-toolbar strong{white-space:nowrap;flex-shrink:0}.calendar-caption{color:#6f818c}.calendar-date small{color:#738691}.calendar-position{font-size:11px}.calendar-ad small{color:#788d98}
@media(max-width:650px){.calendar-toolbar{flex-wrap:wrap;align-items:center}.calendar-toolbar>div{width:100%;justify-content:space-between}.calendar-toolbar>button{margin-left:auto}.calendar-toolbar strong{font-size:16px}.calendar-grid{min-width:0;grid-template-columns:repeat(7,minmax(0,1fr))}.calendar-week{font-size:10px;padding:10px 0}.calendar-day{min-height:68px;padding:7px 3px;text-align:center}.calendar-date{justify-content:center;margin-bottom:9px}.calendar-date b{font-size:14px}.calendar-date small,.calendar-position{display:none}.calendar-mini{display:flex;justify-content:center;gap:3px}.calendar-mini i{width:4px;height:4px;border-radius:50%;background:#dbe3e4}.calendar-mini i.occupied{background:#83a574}.calendar-mini i.full{background:#bc9658}.calendar-pending{font-size:9px;margin-top:7px;white-space:nowrap}.calendar-mobile-tip{display:inline}.calendar-detail .ledger-section-heading{flex-wrap:wrap}.calendar-detail .ledger-section-heading>div{width:100%}.calendar-detail .ledger-section-heading>button{margin-left:auto}}

@media(max-width:650px){.calendar-toolbar>div{display:grid;grid-template-columns:32px minmax(0,1fr) 32px 48px;gap:5px}.calendar-toolbar>div .arco-btn{padding-inline:6px;min-width:0;width:100%}.calendar-toolbar strong{font-size:14px;text-align:center}}
</style>
